  // =========================================================================
  // Test driver
  // =========================================================================
  int          cycle_count;
  string       vmem_path;
  string       covout_path;

  initial begin
    // Required: +vmem=<path>
    if (!$value$plusargs("vmem=%s", vmem_path)) begin
      $fatal(1, "tb_crv_cov: +vmem=<path> required");
    end
    // Optional: +covout=<path> (default: coverage.txt)
    if (!$value$plusargs("covout=%s", covout_path)) begin
      covout_path = "coverage.txt";
    end

    // Load program into memory
    $readmemh(vmem_path, mem);

    // Reset sequence
    cycle_count = 0;
    rst_n = 1'b0;
    repeat (8) @(posedge clk);
    @(negedge clk); rst_n = 1'b1;

    // Run until halt or cycle cap (1 000 000 cycles)
    fork
      begin : wait_halt
        wait (halted > 0);
        // Drain a few cycles for trailing retirements
        repeat (20) @(posedge clk);
      end
      begin : cap
        repeat (1_000_000) @(posedge clk);
        $display("tb_crv_cov: cycle cap reached (no halt in 1M cycles)");
      end
    join_any
    disable fork;

    dump_coverage(covout_path);
    $display("tb_crv_cov: coverage written to %s", covout_path);
    $finish;
  end

  // Cycle counter (informational)
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) cycle_count <= 0;
    else        cycle_count <= cycle_count + 1;
  end

endmodule
